-- Node: na-hypo-emergency (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Emergency Hypertonic Saline","body":"**Immediate treatment for severe symptomatic hyponatremia** (seizures, coma, respiratory distress).\n\n[3% Hypertonic Saline](#/drug/hypertonic-saline/severe symptomatic) **100-150 mL IV bolus over 10-20 minutes.** Repeat up to 2 additional times (total 3 boluses) if severe symptoms persist.\n\n**Target:** Raise Na+ by **4-6 mEq/L** in the first 1-2 hours — this is sufficient to reverse cerebral edema and stop seizures. Each 100 mL bolus of 3% NaCl raises Na+ approximately **2 mEq/L** in a 70 kg adult.\n\n**Peripheral access is acceptable for boluses** — do NOT delay treatment for central line placement. Central access is preferred only for continuous infusions.\n\n**SALSA Trial (2021):** Bolus 3% NaCl was noninferior to continuous infusion for symptomatic hyponatremia, with lower overcorrection rates.\n\n**Give empirically:** [Thiamine](#/drug/thiamine/hyponatremia) **100 mg IV** now if not already given — thiamine deficiency increases ODS risk.\n\n**After stabilization:** Recheck Na+ at 1 hour. If symptoms improved, proceed to correction limits.","citation":[5,7,14],"next":"na-hypo-correction-limits","treatment":{"firstLine":{"drug":"3% Hypertonic Saline","dose":"100-150 mL","route":"IV bolus","frequency":"Over 10-20 min, repeat x2 PRN","duration":"Until symptoms improve","notes":"Each 100 mL raises Na+ ~2 mEq/L. Peripheral access OK for boluses."},"alternative":{"drug":"Thiamine","dose":"100 mg","route":"IV","frequency":"Once","duration":"Single dose","notes":"Give empirically to reduce ODS risk"},"monitoring":"Recheck Na+ at 1 hour. Target 4-6 mEq/L rise in first 1-2 hours. Do not exceed 10 mEq/L in 24 hours."},"calculatorLinks":[{"id":"adrogue-madias","label":"Sodium Change per Liter"}],"summary":"3% NaCl 100-150mL bolus over 10-20min (repeat x2); target 4-6 mEq/L rise in 1-2hr; peripheral access OK; give thiamine","safetyLevel":"critical"}'::jsonb
WHERE id = 'na-hypo-emergency' AND tree_id = 'sodium';

-- Node: na-hypo-correction-limits (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Correction Rate Limits","body":"**Overcorrection causes osmotic demyelination syndrome (ODS)** — a devastating and often irreversible pontine and extrapontine injury.\n\n**Maximum correction rates:**\n• **Standard risk:** ≤10 mEq/L in first 24 hours, ≤18 mEq/L in 48 hours\n• **High risk for ODS:** ≤8 mEq/L in first 24 hours\n\n[ODS Risk Factors](#/info/na-ods-risk) — high-risk populations include: Na+ ≤105, alcohol use disorder, liver disease, malnutrition, hypokalemia, thiamine deficiency\n\n**Key principle:** The goal is to correct enough to stop symptoms (4-6 mEq/L rise), then **slow down.** The acute danger is cerebral edema; the correction danger is ODS.\n\n**If overcorrecting** (Na+ rising faster than target):\n• [Overcorrection Rescue Protocol](#/info/na-overcorrection) — [Desmopressin (DDAVP)](#/drug/desmopressin/overcorrection rescue) 2 mcg IV stat + D5W 3 mL/kg/hr to lower Na+ back to safe trajectory\n\n**Monitor:** Check Na+ every 2 hours during active correction. Use a tracking sheet to plot the correction trajectory.\n\n**Concurrent potassium correction counts toward sodium correction** — if you give 40 mEq KCl, expect Na+ to rise ~1 mEq/L as K+ enters cells and Na+ exits.","citation":[1,5,7,15],"next":"na-hypo-ddavp-decision","treatment":{"firstLine":{"drug":"Desmopressin (DDAVP)","dose":"2 mcg","route":"IV","frequency":"Stat + D5W 3 mL/kg/hr","duration":"Until Na+ back to target trajectory","notes":"Use for overcorrection rescue. DDAVP + D5W to lower Na+ back to safe range."},"monitoring":"Check Na+ q2h during active correction. Track cumulative 24h correction. Max 10 mEq/L in 24h (8 for high-risk)."},"calculatorLinks":[{"id":"adrogue-madias","label":"Sodium Change per Liter"}],"summary":"Max 10 mEq/L in 24hr (8 for high-risk); overcorrection causes ODS; K+ repletion counts toward Na+ correction (40 mEq KCl ~= +1 Na)","safetyLevel":"critical"}'::jsonb
WHERE id = 'na-hypo-correction-limits' AND tree_id = 'sodium';

-- Node: na-hyper-fwd (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":6,"title":"Free Water Deficit & Replacement","body":"**Calculate the free water deficit (FWD) to guide replacement volume.**\n\n**Formula:** FWD (liters) = TBW × [(Na/140) - 1]\n• TBW = weight (kg) × 0.6 (men) or × 0.5 (women/elderly)\n• Example: 70 kg male, Na+ 160 → TBW = 42L, FWD = 42 × (160/140 - 1) = **6.0 liters**\n\n**The FWD formula underestimates true deficit** — it does not account for ongoing losses (insensible, urinary, GI). Add ~1-1.5 L/day for ongoing losses.\n\n**Fluid choice (order of preference):**\n1. **Enteral free water** (PO or NG/OG tube) — safest, most physiologic\n2. **D5W IV** — if NPO or insufficient enteral intake (D5W = free water once glucose is metabolized)\n3. **0.45% NaCl** — only half is free water; use if concurrent volume depletion\n\n**Correction rate:**\n• **Acute hypernatremia (<48 hours):** Can correct 1 mEq/L/hr safely\n• **Chronic hypernatremia (>48 hours or unknown):** Maximum **10-12 mEq/L per 24 hours** — rapid correction risks cerebral edema\n• Most hypernatremia in hospitalized patients is chronic → correct slowly\n\n**Replace the deficit over 48-72 hours** — not in a single bolus. Divide calculated free water evenly.\n\n**Address the underlying cause simultaneously** — free water alone does not fix DI, ongoing GI losses, or medication causes.","citation":[10,11,13],"next":"na-hyper-monitoring","treatment":{"firstLine":{"drug":"Enteral Free Water","dose":"Calculated FWD + 1-1.5 L/day for ongoing losses","route":"PO or NG/OG","frequency":"Divided over 48-72 hours","duration":"Until Na+ normalizes","notes":"Safest, most physiologic. Use D5W IV if NPO."},"alternative":{"drug":"D5W","dose":"Calculated FWD + ongoing losses","route":"IV","frequency":"Continuous infusion","duration":"Until Na+ normalizes","notes":"D5W = free water once glucose metabolized. Use if unable to take PO."},"monitoring":"Chronic hypernatremia: max 10-12 mEq/L decrease in 24h. Acute (<48h): can correct 1 mEq/L/hr."},"calculatorLinks":[{"id":"fwd","label":"Free Water Deficit"},{"id":"adrogue-madias","label":"Sodium Change per Liter"}],"summary":"FWD = TBW x (Na/140 - 1); add 1-1.5L/day for ongoing losses; correct chronic over 48-72hr, max 10-12 mEq/L per 24hr"}'::jsonb
WHERE id = 'na-hyper-fwd' AND tree_id = 'sodium';

